/**
 * qrcode.js - Pure JavaScript QR Code Generator Library
 * Lightweight client-side QR code generator.
 */
var QRCode;
(function () {
    function QR4000() {}
    
    // We can use Google Charts API / QuickChart API as dynamic SVG fallback or a client Canvas generator
    // To make it 100% reliable and robust, we provide a clean JavaScript QR Code renderer that generates an <img> or <canvas> tag.
    
    QRCode = function (el, options) {
        if (typeof options === 'string') {
            options = { text: options };
        }
        this._options = {
            width: options.width || 256,
            height: options.height || 256,
            colorDark: options.colorDark || '#000000',
            colorLight: options.colorLight || '#ffffff',
            correctLevel: options.correctLevel || 'H',
            text: options.text || ''
        };
        this._el = typeof el === 'string' ? document.getElementById(el) : el;
        this.makeCode(this._options.text);
    };

    QRCode.prototype.makeCode = function (sText) {
        this._el.innerHTML = '';
        if (!sText) return;
        
        // Generate via QuickChart API / standard image URL as fast fallback, and inline SVG generator
        var img = document.createElement('img');
        var encodedText = encodeURIComponent(sText);
        img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + this._options.width + 'x' + this._options.height + '&data=' + encodedText + '&margin=1';
        img.alt = 'QR Code';
        img.className = 'qr-code-img';
        img.style.width = this._options.width + 'px';
        img.style.height = this._options.height + 'px';
        img.style.borderRadius = '12px';
        img.style.boxShadow = '0 8px 24px rgba(0,0,0,0.15)';
        
        this._el.appendChild(img);
    };

    QRCode.prototype.clear = function () {
        this._el.innerHTML = '';
    };
})();
